'use strict'

import { getHitboxPath } from '../utils/hitbox'

class Tile {
  constructor (column, line, x, y, width, height, hitbox, sprite, block, destructible, tileTransition, start) {
    this.column = column
    this.line = line
    this.x = x
    this.y = y
    this.width = width
    this.height = height
    this.hitbox = hitbox
    this.sprite = sprite
    this.transition = undefined
    this.tilePath = this.getTilePath()
    this.blockPath = this.getBlockPath()
    this.block = block
    this.destructible = destructible
    this.tileTransition = tileTransition
    this.start = start
  }

  recomputePaths () {
    this.tilePath = this.getTilePath()
    this.blockPath = this.getBlockPath()
  }

  clone () {
    return new Tile(this.column, this.line, this.x, this.y, this.width, this.height, this.hitbox, this.sprite.clone(), this.block, this.destructible, this.tileTransition.clone(), this.start)
  }

  draw (context, offsetX, offsetY) {
    const tileOffsetX = offsetX !== undefined ? this.x + offsetX : this.x
    const tileOffsetY = offsetY !== undefined ? this.y + offsetY : this.y

    this.sprite.draw(context, tileOffsetX, tileOffsetY, this.width, this.height)
  }

  getTilePath () {
    const path = new Path2D()
    path.rect(this.x, this.y, this.width, this.height)

    return path
  }

  getBlockPath () {
    if (typeof this.hitbox !== 'string') {
      return
    }

    return getHitboxPath(this.x, this.y, this.width, this.height, this.hitbox)
  }
}

export { Tile }
